function validate(input) {
  const [{ reactions = [] }] = input;
  const seen = new Set();
  for (const [user, content, reaction] of reactions) {
    if (user === null || content === null || reaction === null) return 'No column may be null.';
    if (seen.has(`${user}|${content}`)) return `User ${user} reacts to content ${content} twice.`;
    seen.add(`${user}|${content}`);
    if (!/^[a-z]+$/.test(reaction)) return `reaction ${reaction} must be a lowercase word.`;
  }
  return null;
}

