function generate(rand, size) {
  const small = size === 'small';
  const pick = n => Math.floor(rand() * n);
  const kinds = ['like', 'love', 'wow', 'sad', 'angry', 'haha'];
  const reactions = [];
  let budget = small ? pick(9) : 2000;
  for (let user = 1; budget > 0; user++) {
    // At most 40 reactions per user keeps the exact and the rounded share on the same side of 60%.
    const count = Math.min(budget, small ? 3 + pick(6) : 1 + pick(40));
    budget -= count;
    const favourite = kinds[pick(small ? 3 : kinds.length)];
    const loyalty = [0.3, 0.6, 0.8, 1][pick(4)];
    const first = 100 * user + pick(50);
    for (let i = 0; i < count; i++) {
      const reaction = rand() < loyalty ? favourite : kinds[pick(small ? 3 : kinds.length)];
      reactions.push([user, first + i, reaction]);
    }
  }
  return [{ reactions }];
}
